<div class="page-heading"><div><p class="context">Flux sortant</p><h1>Préparation & expédition</h1><p>Réservez en FEFO, confirmez les prélèvements et chargez le camion.</p></div><?php if(Auth::can($user,'manage_orders')): ?><a class="button" href="/?page=catalog&t=customer_order&new=1">Nouvelle commande</a><?php endif; ?></div>
<?php if(Auth::can($user,'manage_orders')): ?><section class="workflow-strip no-print"><a href="/?page=catalog&t=order_line">Articles de commande</a><a href="/?page=catalog&t=package">Constituer les colis</a><a href="/?page=catalog&t=package_pick">Affecter leur contenu</a></section><?php endif; ?>
<p class="hint">Les DLC les plus proches sortent d’abord, puis les lots sans DLC. Lots bloqués et périmés exclus. La réservation porte sur la commande complète ; annuler libère les quantités. Le débit de stock intervient au chargement confirmé.</p>
<form method="get" class="filters"><input type="hidden" name="page" value="orders"><?php inputField('q','Référence',$_GET['q']??'','search',false);selectField('status','État',array_map(fn($v)=>['id'=>$v,'label'=>Catalog::VALUES[$v]],['draft','picking','ready','shipped','cancelled']),$_GET['status']??'',true);selectField('owner_id','Propriétaire',$catalog->options('owner'),$_GET['owner_id']??'',true);selectField('preparer_id','Préparateur',$catalog->options('user_account'),$_GET['preparer_id']??'',true);inputField('desired_from','Expédition à partir du',$_GET['desired_from']??'','date',false);inputField('desired_to','Expédition jusqu’au',$_GET['desired_to']??'','date',false);filterEnd('orders'); ?>
<?php $where=['1=1'];$params=[];if($user['role']==='warehouse'){$where[]='o.preparer_id=?';$params[]=$user['id'];}if(!empty($_GET['q'])){$where[]='o.reference LIKE ?';$params[]='%'.$_GET['q'].'%';}if(!empty($_GET['status'])){$where[]='o.status=?';$params[]=$_GET['status'];}foreach(['owner_id','preparer_id'] as $key)if(!empty($_GET[$key])){$where[]='o.'.$key.'=?';$params[]=(int)$_GET[$key];}if(!empty($_GET['desired_from'])){$where[]='o.desired_on>=?';$params[]=Warehouse::date($_GET['desired_from']);}if(!empty($_GET['desired_to'])){$where[]='o.desired_on<=?';$params[]=Warehouse::date($_GET['desired_to']);}$p=max(1,(int)($_GET['p']??1));$total=(int)$db->scalar('SELECT COUNT(*) FROM customer_order o WHERE '.implode(' AND ',$where),$params);$orders=$db->all('SELECT o.*,c.name owner_name,u.name preparer FROM customer_order o JOIN owner c ON c.id=o.owner_id LEFT JOIN user_account u ON u.id=o.preparer_id WHERE '.implode(' AND ',$where).' ORDER BY o.id DESC LIMIT 20 OFFSET '.(($p-1)*20),$params);foreach($orders as $o): ?>
<article class="panel"><div class="section-heading"><div><h2><a href="<?= h(url(['page'=>'order_detail','id'=>$o['id']])) ?>"><?= h($o['reference']) ?></a></h2><p><?= h($o['owner_name']) ?> · Expédition souhaitée : <?= h($o['desired_on']) ?></p></div><?= badge($o['status']) ?></div><p><?= h($o['destination']) ?></p><?php dataTable($db->all('SELECT a.sku article,a.name designation,ol.qty quantite FROM order_line ol JOIN article a ON a.id=ol.article_id WHERE ol.order_id=?',[$o['id']]));if($o['preparer']): ?><p>Préparateur : <?= h($o['preparer']) ?></p><?php endif; ?>
<div class="actions no-print"><?php if($o['status']==='draft'&&Auth::can($user,'manage_orders')){startForm('assign_preparer',['id'=>$o['id']],'inline-form');selectField('preparer_id','Affecter à',$db->all("SELECT id,CONCAT(name,' / ',role) label FROM user_account WHERE active=1 AND role='warehouse' ORDER BY name")); ?><button>Affecter le préparateur</button></form><?php }elseif($o['status']==='draft'&&$user['role']==='warehouse'){startForm('prepare',['id'=>$o['id']]); ?><button>Lancer le prélèvement FEFO</button></form><?php }elseif($o['status']==='picking'&&$user['role']==='warehouse'){startForm('confirm',['id'=>$o['id']]); ?><button>Confirmer tous les prélèvements</button></form><?php }elseif($o['status']==='ready'&&$user['role']==='warehouse'){startForm('ship',['id'=>$o['id']],'inline-form');selectField('visit_id','Camion au chargement',$db->all("SELECT id,reference label FROM truck_visit WHERE status='working' AND operation='expedition' ORDER BY id DESC")); ?><button>Confirmer l’expédition</button></form><?php }if(Auth::can($user,'manage_orders')&&!in_array($o['status'],['shipped','cancelled'],true)){startForm('cancel_order',['id'=>$o['id']]); ?><button class="secondary" data-confirm="Annuler cette commande et libérer ses réservations ?">Annuler</button></form><?php } ?><a class="button secondary" href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'pick'])) ?>">Liste de prélèvement</a><?php if($o['status']==='shipped'): ?><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'delivery'])) ?>">Bon de livraison</a><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'waybill'])) ?>">Lettre de voiture</a><?php endif; ?></div></article><?php endforeach;if(!$orders): ?><p class="empty">Aucune commande pour ces critères.</p><?php endif;pagination($total,$p); ?>
